import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"ADR 0001: AI Provider Fallback Strategy & Rate Limit Mitigation","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/0001-ai-provider-fallback-strategy.md","filePath":"architecture/decisions/0001-ai-provider-fallback-strategy.md"}`),a={name:`architecture/decisions/0001-ai-provider-fallback-strategy.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="adr-0001-ai-provider-fallback-strategy-rate-limit-mitigation" tabindex="-1">ADR 0001: AI Provider Fallback Strategy &amp; Rate Limit Mitigation <a class="header-anchor" href="#adr-0001-ai-provider-fallback-strategy-rate-limit-mitigation" aria-label="Permalink to &quot;ADR 0001: AI Provider Fallback Strategy &amp; Rate Limit Mitigation&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2024-05-20</p><h2 id="_1-context-and-problem" tabindex="-1">1. Context and Problem <a class="header-anchor" href="#_1-context-and-problem" aria-label="Permalink to &quot;1. Context and Problem&quot;">​</a></h2><p>TechyNews relies heavily on AI for automated news aggregation and generation. During peak generation cycles, relying on a single AI provider creates a Single Point of Failure (SPOF). Network timeouts, API outages, or HTTP 429 (Too Many Requests) errors would halt the content pipeline entirely, leaving the platform without fresh content.</p><p>We needed a resilient architecture that guarantees high availability for the content generation pipeline without significantly increasing operational costs or exposing API keys on the client side.</p><h2 id="_2-considered-options" tabindex="-1">2. Considered Options <a class="header-anchor" href="#_2-considered-options" aria-label="Permalink to &quot;2. Considered Options&quot;">​</a></h2><ul><li><strong>Option A: Naive Retry with Exponential Backoff (Single Provider).</strong> Pausing the queue and retrying. (Rejected: Doesn&#39;t solve provider-side outages).</li><li><strong>Option B: Multiple Google Cloud Accounts.</strong> (Rejected: Violates Terms of Service and adds billing complexity).</li><li><strong>Option C: Provider Fallback Chain (Gemini -&gt; OpenRouter).</strong></li></ul><h2 id="_3-decision" tabindex="-1">3. Decision <a class="header-anchor" href="#_3-decision" aria-label="Permalink to &quot;3. Decision&quot;">​</a></h2><p>We selected <strong>Option C: Implement a Fallback Chain Strategy.</strong></p><ol><li><strong>Primary Provider:</strong> Google Gemini 2.0 Flash is used as the primary LLM due to its exceptional speed-to-cost ratio and large context window.</li><li><strong>Secondary Provider (Fallback):</strong> OpenRouter is configured as a fallback proxy.</li><li><strong>Implementation:</strong> If the primary Gemini request fails (e.g., due to rate limits or 5xx errors), the backend Exception Handler intercepts the failure, logs the incident with context, and seamlessly routes the identical prompt to the OpenRouter fallback adapter.</li><li><strong>Throttling:</strong> A mandatory 10-second delay was introduced in the content generation queue between successful calls to proactively respect provider rate limits.</li></ol><h2 id="_4-consequences" tabindex="-1">4. Consequences <a class="header-anchor" href="#_4-consequences" aria-label="Permalink to &quot;4. Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive: <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive:&quot;">​</a></h3><ul><li><strong>High Availability:</strong> The content pipeline is now fault-tolerant. Temporary Gemini outages no longer halt platform updates.</li><li><strong>Cost Efficiency:</strong> We maintain the low cost of Gemini 2.0 Flash for ~95% of operations, only incurring OpenRouter costs during emergency failovers.</li><li><strong>Security:</strong> All LLM interactions remain strictly server-side, preventing API key leakage.</li></ul><h3 id="negative-trade-offs" tabindex="-1">Negative / Trade-offs: <a class="header-anchor" href="#negative-trade-offs" aria-label="Permalink to &quot;Negative / Trade-offs:&quot;">​</a></h3><ul><li><strong>Architectural Complexity:</strong> Requires maintaining multiple AI service adapters in the Laravel backend to normalize request/response payloads across different APIs.</li><li><strong>Latency Spikes:</strong> During a failover event, the total request latency increases (Primary Timeout + Fallback Generation Time), though this is acceptable for background queue jobs.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};